ca_test('teacher is linked once and receives assigned scope only',function()use($c,$teacherAccount,$teacher){ca_ok($c->account($teacherAccount)['teacher_doc_id']===$teacher);ca_ok($c->permissions($teacherAccount)['grading.grades.enter']==='ASSIGNED');ca_ok(!$c->can($teacherAccount,'grading.grades.finalize'));ca_ok(!$c->can($teacherAccount,'sis.payments.receive'));ca_denied(fn()=>ca_create('duplicate.teacher','TEACHER',['teacher_doc_id'=>$teacher]));});
ca_test('non Power User cannot create or reset accounts',function()use($c,$teacherAccount,$studentAccount){ca_denied(fn()=>$c->save($teacherAccount,['full_name'=>'Bad','username'=>'bad.user','group'=>'POWER_USER','status'=>'ACTIVE','temp_password'=>'Temporary12345']));ca_denied(fn()=>$c->setPassword($studentAccount,'HackedPassword123',true,$teacherAccount));});
ca_test('default Registrar Accounting and Student permissions match their boundaries',function()use($c,$registrar,$accounting,$studentAccount){ca_ok($c->can($registrar,'grading.workspace.view')&&$c->can($registrar,'sis.admission.manage'));ca_ok(!$c->can($registrar,'sis.payments.receive'));ca_ok($c->can($accounting,'sis.payments.receive')&&$c->can($accounting,'sis.journals.post'));ca_ok(!$c->can($accounting,'grading.workspace.view'));ca_ok($c->permissions($studentAccount)['portal.grades.view']==='OWN');ca_ok(!$c->can($studentAccount,'grading.students.view'));});
ca_test('teacher usernames use first initial and full surname',function(){foreach(['Juan Cruz'=>'jcruz','Juan Dela Cruz'=>'jdelacruz','ALLAN L. BALBACAL, RRT'=>'abalbacal','Juan M. Dela Cruz, LPT'=>'jdelacruz','Maria L. de la Cruz'=>'mdelacruz','John Smith-Jones'=>'jsmithjones','José Niño'=>'jnino','Juan Cruz Jr.'=>'jcruz'] as $name=>$expected)ca_ok(CentralAccounts::teacherUsernameBase($name)===$expected,$name);ca_denied(fn()=>CentralAccounts::teacherUsernameBase('Juan'));ca_denied(fn()=>CentralAccounts::teacherUsernameBase('Dela Cruz, Juan Miguel'));});
ca_test('teacher shortcut automatically creates a linked Teacher account and temporary password',function()use($c,$power){Auth::actAs((int)$c->legacyId($power,'SIS'));$tid=GS::saveTeacher(null,'AUTO001','Automatic Teacher');$r=$c->createTeacherAccount($power,$tid);ca_ok($r['username']==='ateacher');ca_ok($c->verifyPassword($r['account_id'],$r['temporary_password']));ca_ok((bool)$c->account($r['account_id'])['must_change_password']);ca_ok($c->account($r['account_id'])['teacher_doc_id']===$tid);ca_ok($c->group($r['account_id'])==='TEACHER');ca_ok($c->legacyId($r['account_id'],'SIS')!==null&&$c->legacyId($r['account_id'],'GRADING')!==null);$hash=Db::val('SELECT password_hash FROM central_credentials WHERE account_id=?',[$r['account_id']]);ca_denied(fn()=>$c->createTeacherAccount($power,$tid));ca_ok(Db::val('SELECT password_hash FROM central_credentials WHERE account_id=?',[$r['account_id']])===$hash);});
