ca_test('teacher shortcut never duplicates a legacy teacher account',function()use($c,$power){Auth::actAs((int)$c->legacyId($power,'SIS'));$tid=GS::saveTeacher(null,'AUTO003','Legacy Teacher');Db::q("INSERT INTO docs(col,id,data) VALUES('users','legacy_shortcut_teacher',?)",[json_encode(['username'=>'old.auto003','teacherDocId'=>$tid,'role'=>'teacher','active'=>true])]);$count=Db::val('SELECT COUNT(*) FROM central_accounts');ca_denied(fn()=>$c->createTeacherAccount($power,$tid));ca_ok(Db::val('SELECT COUNT(*) FROM central_accounts')===$count);});
ca_test('temporary password flags and shared self password change work',function()use($c,$teacherAccount){$a=$c->login('CENTRAL.TEACHER','Temporary12345','GRADING');ca_ok((bool)$a['must_change_password']);$c->changePassword($teacherAccount,'Temporary12345','MyNewPassword123');ca_ok(!$c->account($teacherAccount)['must_change_password']);ca_ok(!$c->verifyPassword($teacherAccount,'Temporary12345'));ca_ok($c->login('central.teacher','MyNewPassword123','SIS')['id']==$teacherAccount);});
